"""
Generated grid: dorm a125 advgen. Cross-verified cell by cell at emit time.

Failure-Class: FC-bare-batch-pipeline-lanes-collide-inside-armed-storm-window

Each test re-drives its cell through the real boundary
(``drive_cell``) and compares the full observable freeze against the
literal the emit-time cross-verify produced; the independent model walk and
the emitter live outside the tree. Do not edit frozen literals by hand.
"""

from tests.unit.batch_lane_storm_gate_grid_harness import drive_cell


def _drive(monkeypatch, caplog, **params):
    return drive_cell(monkeypatch, caplog, **params)


def test_abaa_enaa_rsaa_wvaa_geaa_hoaa_loaa(monkeypatch, caplog) -> None:
    assert _drive(
        monkeypatch,
        caplog,
        label='batch_privacy_generation_advance',
        aborts=0,
        entry_wait=0.0,
        residual_schedule=(0.0,),
        wave_wait=0.0,
        generation=0,
        hostile_peek=False,
        damper_mode='dormant_none',
        log_mode='info',
        arm_window=1.25,
    ) == {
        'result': 'joined',
        'raised': None,
        'retry_after': 0.0,
        'body_calls': [1],
        'sleeps': [],
        'damper_slept': [],
        'events': [],
        'note_success': [],
        'consult_count': 0,
        'peek_count': 0,
        'records': [],
    }


